1	type Item = { type: string; material?: string; cursed?: boolean; enchantment?: number };
2	
3	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
4	
5	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
6	
7	const BLOCK_SIZE = 3;
8	const BLOCK_PREMIUM = 60;
9	
10	const sumBy = <T>(values: T[], valueOf: (value: T) => number): number =>
11	  values.reduce((sum, value) => sum + valueOf(value), 0);
12	
13	const valueForType = (table: Record<string, number>, item: Item): number => {
14	  const value = table[item.type];
15	  if (value === undefined) {
16	    throw new Error(`Unknown item type: ${item.type}`);
17	  }
18	  return value;
19	};
20	
21	const basePremiumForItem = (item: Item): number =>
22	  valueForType(basePremiumsByType, item);
23	
24	const sumOfItemBasePremiums = (items: Item[]): number =>
25	  sumBy(items, basePremiumForItem);
26	
27	const groupByType = (items: Item[]): Item[][] => {
28	  const groups = new Map<string, Item[]>();
29	  for (const item of items) {
30	    const group = groups.get(item.type) ?? [];
31	    group.push(item);
32	    groups.set(item.type, group);
33	  }
34	  return [...groups.values()];
35	};
36	
37	const basePremiumForGroup = (group: Item[]): number =>
38	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
39	
40	export const basePremium = (items: Item[]): number =>
41	  sumBy(groupByType(items), basePremiumForGroup);
42	
43	const PROCESSING_FEE = 5;
44	
45	type Customer = { yearsWithMHPCO: number };
46	type QuoteStep = { op: "quote"; items: Item[] };
47	type Damage = { itemType: string; amount: number };
48	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
49	type Step = QuoteStep | ClaimStep;
50	type Scenario = { customer: Customer; steps: Step[] };
51	
52	type QuoteResult = { premium: number };
53	type ClaimResult = { payout: number; remainingCap: number };
54	type StepResult = QuoteResult | ClaimResult;
55	
56	const CURSE_SURCHARGE_RATE = 0.5;
57	const HIGH_ENCHANTMENT_RATE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const FIRST_INSURANCE_RATE = 0.1;
60	const LOYALTY_RATE = 0.2;
61	const LOYALTY_THRESHOLD = 2;
62	const FOLLOWUP_RATE = 0.15;
63	
64	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
65	
66	const curseSurchargeForItem = (item: Item): number =>
67	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
68	
69	const curseSurcharge = (items: Item[]): number =>
70	  sumBy(items, curseSurchargeForItem);
71	
72	const highEnchantmentSurchargeForItem = (item: Item): number =>
73	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD
74	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
75	    : 0;
76	
77	const highEnchantmentSurcharge = (items: Item[]): number =>
78	  sumBy(items, highEnchantmentSurchargeForItem);
79	
80	const rateOfPolicyBase = (policyBase: number, rate: number): number => policyBase * rate;
81	
82	const firstInsuranceSurcharge = (policyBase: number): number =>
83	  rateOfPolicyBase(policyBase, FIRST_INSURANCE_RATE);
84	
85	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
86	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? rateOfPolicyBase(policyBase, LOYALTY_RATE) : 0;
87	
88	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
89	  isFollowUp ? rateOfPolicyBase(policyBase, FOLLOWUP_RATE) : 0;
90	
91	const itemSurcharges = (items: Item[]): number =>
92	  curseSurcharge(items) + highEnchantmentSurcharge(items);
93	
94	// MHPCO always keeps the fraction: a premium is money owed *to* MHPCO,
95	// so rounding up (a higher premium) lands the fraction in its favor.
96	const roundPremiumInFavorOfMHPCO = (premium: number): number => Math.ceil(premium);
97	
98	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
99	  const policyBase = basePremium(step.items);
100	  const surcharges = itemSurcharges(step.items) + firstInsuranceSurcharge(policyBase);
101	  const discounts = loyaltyDiscount(policyBase, customer) + followUpDiscount(policyBase, isFollowUp);
102	  return roundPremiumInFavorOfMHPCO(policyBase + surcharges - discounts + PROCESSING_FEE);
103	};
104	
105	const DEDUCTIBLE = 100;
106	const CAP_MULTIPLIER = 2;
107	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
108	const REDUCED_REIMBURSEMENT_RATE = 0.5;
109	
110	const insuranceValuesByType: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };
111	
112	const insuranceValue = (item: Item): number => valueForType(insuranceValuesByType, item);
113	
114	const insuranceSum = (items: Item[]): number =>
115	  sumBy(items, insuranceValue);
116	
117	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
118	
119	const reimbursableValue = (damageAmount: number, item: Item): number =>
120	  enchantmentLevel(item) >= REDUCED_REIMBURSEMENT_THRESHOLD
121	    ? damageAmount * REDUCED_REIMBURSEMENT_RATE
122	    : damageAmount;
123	
124	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
125	  items.find((item) => item.type === damage.itemType) as Item;
126	
127	const payoutForDamage = (damage: Damage, items: Item[]): number =>
128	  reimbursableValue(damage.amount, insuredItemFor(damage, items)) - DEDUCTIBLE;
129	
130	// The deductible in payoutForDamage applies once per damage entry, so the
131	// incident payout is simply the sum across every damage in the incident.
132	const incidentPayout = (damages: Damage[], items: Item[]): number =>
133	  sumBy(damages, (damage) => payoutForDamage(damage, items));
134	
135	// MHPCO always keeps the fraction: a payout is money owed *by* MHPCO,
136	// so rounding down (a lower payout) lands the fraction in its favor.
137	const roundPayoutInFavorOfMHPCO = (payout: number): number => Math.floor(payout);
138	
139	const countBy = <T>(values: T[], typeOf: (value: T) => string): Map<string, number> => {
140	  const counts = new Map<string, number>();
141	  for (const value of values) {
142	    const type = typeOf(value);
143	    counts.set(type, (counts.get(type) ?? 0) + 1);
144	  }
145	  return counts;
146	};
147	
148	const validateDamagesCovered = (damages: Damage[], items: Item[]): void => {
149	  const insuredCounts = countBy(items, (item) => item.type);
150	  const damageCounts = countBy(damages, (damage) => damage.itemType);
151	  for (const [type, damagedCount] of damageCounts) {
152	    const insuredCount = insuredCounts.get(type) ?? 0;
153	    if (damagedCount > insuredCount) {
154	      throw new Error(`Claim damages more ${type} items than are insured`);
155	    }
156	  }
157	};
158	
159	const validateDamageAmounts = (damages: Damage[]): void => {
160	  for (const damage of damages) {
161	    if (damage.amount < 0) {
162	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
163	    }
164	  }
165	};
166	
167	const validateClaim = (damages: Damage[], insuredItems: Item[]): void => {
168	  validateDamagesCovered(damages, insuredItems);
169	  validateDamageAmounts(damages);
170	};
171	
172	const claimResult = (step: ClaimStep, scenario: Scenario, alreadyPaid: number): ClaimResult => {
173	  const policyStep = scenario.steps[step.policy] as QuoteStep;
174	  validateClaim(step.incident.damages, policyStep.items);
175	  const capBeforeClaim = policyCap(policyStep.items) - alreadyPaid;
176	  const desiredPayout = roundPayoutInFavorOfMHPCO(incidentPayout(step.incident.damages, policyStep.items));
177	  const payout = Math.min(desiredPayout, capBeforeClaim);
178	  return { payout, remainingCap: capBeforeClaim - payout };
179	};
180	
181	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
182	  const paidByPolicy = new Map<number, number>();
183	  const results = scenario.steps.map((step, index) => {
184	    if (step.op === "quote") {
185	      return { premium: quotePremium(step, scenario.customer, index > 0) };
186	    }
187	    const alreadyPaid = paidByPolicy.get(step.policy) ?? 0;
188	    const result = claimResult(step, scenario, alreadyPaid);
189	    paidByPolicy.set(step.policy, alreadyPaid + result.payout);
190	    return result;
191	  });
192	  return { results };
193	};
